/*
 * MAX7219 Heart Beat - animate a beating heart on an 8x8 LED matrix.
 *
 * Wiring (Arduino Uno to MAX7219):
 *   5V  to VCC
 *   GND to GND
 *   D11 to DIN
 *   D10 to CS
 *   D13 to CLK
 */

#define DIN_PIN  11
#define CLK_PIN  13
#define CS_PIN   10

// Heart bitmap - bit 0 = leftmost column
const byte heart[8] = {
  0b00011000,
  0b00111100,
  0b01111110,
  0b11111111,
  0b11111111,
  0b01111110,
  0b00111100,
  0b00011000
};

void sendByte(byte data) {
  for (int i = 7; i >= 0; i--) {
    digitalWrite(CLK_PIN, LOW);
    digitalWrite(DIN_PIN, (data >> i) & 1);
    digitalWrite(CLK_PIN, HIGH);
  }
}

void sendCommand(byte cmd, byte data) {
  digitalWrite(CS_PIN, LOW);
  sendByte(cmd);
  sendByte(data);
  digitalWrite(CS_PIN, HIGH);
}

void clearDisplay() {
  for (int row = 0; row < 8; row++) {
    sendCommand(row + 1, 0x00);
  }
}

void drawHeart() {
  for (int row = 0; row < 8; row++) {
    sendCommand(row + 1, heart[row]);
  }
}

void setup() {
  pinMode(DIN_PIN, OUTPUT);
  pinMode(CLK_PIN, OUTPUT);
  pinMode(CS_PIN, OUTPUT);

  // Initialize MAX7219
  sendCommand(0x0B, 0x07);  // Scan limit: 8 digits
  sendCommand(0x09, 0x00);  // Decode mode: no decode
  sendCommand(0x0A, 0x0F);  // Intensity: max
  sendCommand(0x0C, 0x01);  // Shutdown: normal mode
  sendCommand(0x0F, 0x00);  // Display test: off

  clearDisplay();
  Serial.begin(115200);
  Serial.println("MAX7219 heart beat started");
}

void loop() {
  // Two pulses for a realistic heart beat
  drawHeart();
  delay(400);
  drawHeart();
  delay(400);
  clearDisplay();
  delay(200);
}
